<template>
    <div class="modal d-block my-popups dialog">
        <div class="modal-dialog">
            <div class="modal-content">
                <div class="modal-header">
                    <slot name="header">
                        <h5 class="modal-title">{{ $t("Sign In") }} </h5>
                    </slot>
                    <button type="button" href="javascript:;" class="close" @click="CloseSigInAgain">
                        <em class="fa fa-times"></em> 
                    </button>
                </div>
                <div class="modal-body">
                    <body style="font-family: Arial, sans-serif; display: flex; justify-content: center; align-items: center; height: 20vh; margin: 0; background-color: #f4f4f4;">
                        <div style="text-align: center; padding: 20px; background-color: #fff; border-radius: 8px; box-shadow: 0 0 10px rgba(0,0,0,0.1);">
                            <p style="font-size: 18px; color: #333; margin-bottom: 20px;">
                                Your session has expired. Please 
                                <a @click="SignInAgain" style="padding: 10px 20px; font-size: 16px; color: #fff; background-color: #007bff; border: none; border-radius: 5px; text-decoration: none; cursor: pointer;">
                                    Sign in again
                                </a>
                            </p>
                        </div>
                    </body>
                </div>
            </div>
        </div>
    </div>
</template>
<script>
import DataService from '../../../services/DataService';
export default{
    props:{
        additionalStorage:null
    },
   methods:{
    SignInAgain:function(){
        var vm=this;
        var params=`name=${vm.Name}&additionalStorageId=${vm.additionalStorage}`
        DataService.GetAuthorizationUrl(params).then((response) => {
            debugger;
            window.location.href=response.data.authorizationUrl;
            
        })
    },
    CloseSigInAgain:function(){
        var vm=this;
        vm.$emit("CloseSigInAgain");
    }
   }
}
</script>
