<template>
    <div class="my-popups">
        <div class="modal d-block ">
            <div class="modal-dialog">
                <div class="modal-content">
                    <div class="modal-header ui-draggable-handle">
                        <h4 name="header" class="modal-title">
                            {{$t('SelectParentFolder')}}
                        </h4>
                        <button @click="closepopup" class="close"><em aria-hidden="true"
                                class="fa fa-times"></em> </button>
                    </div>
                    <div class="">
                        <div id="main" class="collapse show px-3 py-2 border FullTreeData" style="max-height:90vh; overflow-y: auto;">
                            <DocCommonTreeView  :checkActionType="checkActionType" treeId="MoveTree" :dynamicLeftMenu="dynamicLeftMenu" :AdditionalStorageId="AdditionalStorageId" @Folderlisting="Folderlisting" :mySpaceOrOrganization="mySpaceOrOrganization" :organizationSpace="organizationSpace"  :type="checkType" :MySpaceFolders="FolderArray" @FolderIdMoveLeftMenu="FolderIdMoveLeftMenu" :FolderIdMoveLeftMenu="FolderIdMoveLeftMenu"></DocCommonTreeView>                          
                        </div>
                    </div>
                    <div class="modal-footer text-right pr-0 pb-0">
                        <button title="Cancel" @click="closepopup"
                            class="popupredbtn btn btn-danger formbtn widthhalf pr-2"><em aria-hidden="true"
                                class="fa fa-times pr-2"></em>{{$t('Cancel')}}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>
<script>
import ChildFolder from "./ChildFolder.vue";
import DataService from "../services/DataService";
import DocCommonTreeView from "./DocCommonTreeView.vue";
export default {
    components: {
    ChildFolder,
    DocCommonTreeView
},
    props:{
        defaultData:{
            type: Array,
            required: false,
        },
        FolderIdMoveLeftMenu:{
            type: Function,
            required: false
        },
        mySpaceOrOrganization:{
            type: Number,
            required: false
        },
        FolderArray:{
            type: Array,
            required: true,
        },
        AdditionalStorageId:{
            type: String,
            required: false
        },
        folderids: {
            type: String,
            required: false
        },
        checkType:{
            type: String,
            required: false
        }
    },
    data() {
        return {
            loggeduserid: null,
            folderarray: [],
            FindalFolderArray: [],
            FilesListingData: [],
            folderTreeList: [],
            sharedFolder: [],
            folderidManagePopup: null,
            organizationSpace:[]
        }
    },
    created: function () {
        debugger
        var vm=this;
        $("body").on("click", "#FolderFullTree .folderlink", function () {
            $(".folderlink").removeClass("selectedfolder");
            $(this).addClass("selectedfolder");
        });
        this.loggeduserid = this.GetUserInfo.ID;
        this.GetFullTree();
        if(vm.mySpaceOrOrganization==1){
            if(vm.AdditionalStorageId==0 || vm.AdditionalStorageId==null){
                vm.AdditionalStorageId="Default"
                vm.organizationSpace=vm.defaultData;
            }
            else{
                vm.GetOrganizationSpace(vm.AdditionalStorageId);
            }
        }
        else{
            if(vm.AdditionalStorageId==0 || vm.AdditionalStorageId==undefined){
                vm.AdditionalStorageId="Default"
                vm.FolderArray=vm.defaultData;
            }else{
                vm.GetAdditionalFullTree(vm.AdditionalStorageId);
            }
        }
    },
    mounted: function () {
        $("body").on("click", "#FolderFullTree .folderlink", function () {
            $(".folderlink").removeClass("selectedfolder");
            $(this).addClass("selectedfolder");
        });
    },
    methods: {
        GetOrganizationSpace: function (id) {

        var vm = this;
        vm.organizationSpace=[]
        vm.additionalOrganizationSpace=[];
        vm.dynamicLeftMenu=[];
        DataService.GetOrganizationFolderTreeData().then((response) => {
            response.data.folderTreeList.forEach((value, index) => {
                var CheckIfExist = vm.organizationSpace.filter(function (el) {
                    return el.FOLDER_ID == value.FOLDER_ID;
                });
                if (CheckIfExist.length == 0) {
                    if(parseInt(value.additional_storage_id)==parseInt(id) && value.IsGlobal!=-1){
                        if (value.FOLDER_PARENT_ID == null) {
                            let folderId = value.FOLDER_ID
                            let rslt = vm.getsharedChildFolder(folderId, value, vm.folderTreeList);
                            vm.organizationSpace.push(rslt)
                        }
                    }
                }
                if(value.IsGlobal==-1 && parseInt(value.additional_storage_id)==parseInt(id)){
                    vm.dynamicLeftMenu.push(value)
                }
            });
        });
        },
        GetFullTree() {            
            var vm = this;
            vm.isLoading=true;
            var params = JSON.stringify(vm.moveObj);
            DataService.MoveFolderTreeView(params).then((response) => {
                response.data.folderTreeList.forEach((value, index) => {
                    //vm.sharedfolders(value)
                    if (value.OWNER_USER_ID == this.loggeduserid && value.IsGlobal == 0 && value.additional_storage_id==null) {
                        var CheckIfExist = vm.FindalFolderArray.filter(function (el) {
                            return el.FOLDER_ID == value.FOLDER_ID;
                        });


                        if (CheckIfExist.length == 0) {
                            if (value.FOLDER_PARENT_ID == null) {
                                let folderId = value.FOLDER_ID
                                let rslt = vm.getChildFolder(folderId, value, response.data.folderTreeList)
                                vm.FindalFolderArray.push(rslt)
                            }
                        }

                    }

                });
                vm.folderTreeList = response.data.folderTreeList;
                vm.isLoading = false;
            });
        },
        getChildFolder: function (folderId, currentItem, data) {
            let ths = this;
            let retrunArray = currentItem
            var childArray = data.filter(function (el) {
                return el.FOLDER_PARENT_ID == folderId;
            });
            let finalChildArray = [];
            childArray.forEach((value, index) => {
                let ChildfolderId = value.FOLDER_ID
                var CheckIfExist1 = finalChildArray.filter(function (el) {
                    return el.FOLDER_ID == value.FOLDER_ID;
                });
                if (CheckIfExist1.length == 0) {
                    var CheckIfExist = data.filter(function (el) {
                        return el.FOLDER_PARENT_ID == ChildfolderId;
                    });
                    if (CheckIfExist != null && CheckIfExist.length > 0) {
                        let rslt = ths.getChildFolder(ChildfolderId, value, data);
                        finalChildArray.push(rslt);
                    } else {
                        finalChildArray.push(value);
                    }
                }
            });
            retrunArray.chidFolder = finalChildArray;
            return retrunArray
        },
        // GetOrganizationSpace: function () {
            
        //     var vm = this;
        //     DataService.GetOrganizationFolderTreeData().then((response) => {
        //         response.data.folderTreeList.forEach((value, index) => {
        //             var CheckIfExist = vm.organizationSpace.filter(function (el) {
        //                 return el.FOLDER_ID == value.FOLDER_ID;
        //             });


        //             if (CheckIfExist.length == 0) {
        //                 if (value.FOLDER_PARENT_ID == null) {
        //                     let folderId = value.FOLDER_ID
        //                     let rslt = vm.getsharedChildFolder(folderId, value, vm.folderTreeList);
        //                     vm.organizationSpace.push(rslt)
        //                 }
        //             }
        //         });
        //     });


        // },
        GetAdditionalFullTree(id) {
            var vm = this;
            vm.FolderArray=[];
            DataService.FolderFullTreeView().then((response) => {
                response.data.folderTreeList.forEach((value, index) => {
                    if (value.OWNER_USER_ID == vm.loggeduserid && value.IsGlobal == 0 && value.additional_storage_id!=null) {
                        if (value.FOLDER_PARENT_ID == null && parseInt(value.additional_storage_id)==parseInt(id)) {
                            let folderId = value.FOLDER_ID
                            let rslt = vm.getsharedChildFolder(folderId, value, vm.folderTreeList)
                            vm.FolderArray.push(rslt)
                            vm.RefreshDocCommon++;
                        }
                    }
                });
            });
        },
        getsharedChildFolder: function (folderId, currentItem, data) {
            
            let ths = this;
            let retrunArray = currentItem
            var childArray = data.filter(function (el) {
                return el.FOLDER_PARENT_ID == folderId;
            });
            let finalChildArray = [];
            childArray.forEach((value, index) => {
                let ChildfolderId = value.FOLDER_ID
                var CheckIfExist1 = finalChildArray.filter(function (el) {
                    return el.FOLDER_ID == value.FOLDER_PARENT_ID;
                });
                if (CheckIfExist1.length == 0) {
                    var CheckIfExist = data.filter(function (el) {

                        return el.FOLDER_PARENT_ID == ChildfolderId;


                    });
                    if (CheckIfExist != null && CheckIfExist.length > 0) {
                        let rslt = ths.getsharedChildFolder(ChildfolderId, value, data);
                        finalChildArray.push(rslt);
                    } else {
                        finalChildArray.push(value);
                    }
                }
            });
            retrunArray.chidFolder = finalChildArray;
            return retrunArray
        },
        closepopup: function () {
            
            this.$emit("closepopupmovefolder");
        },
        savebreadcrumb: function () {
            var vm=this;
            this.$emit("BreadCrumb",vm.folderidmanagePopup)
            this.$emit("closepopup");
        },
        FolderIdMoveLeftMenu(data,parentid,actionVal,name) {
            
            var vm=this;
            vm.folderidmanagePopup = name;
            this.$emit("FolderIdManagePopup", data,parentid,actionVal,name)
        }
    }
}
</script>