<script>

import LeftMenu from "@/components/LeftMenu.vue"
import Ownertree from "@/components/OwnerTree.vue"
import RightContent from "@/components/RightContent.vue"
import Listing from "@/components/FIlesListing.vue"
import DataService from "../../services/DataService";
import ManageFolder from "@/views/UI/Manage.vue"
import ModalAddGroup from "./Modal/ModalAddGroup.vue"
import docShare from "@/views/UI/ShareDocument.vue"
import ModalAddTag from "./Modal/ModalAddTag.vue"
import ModalMoveFolderFiles from "./Modal/ModalMoveFolderFiles.vue"
import GlobalListing from "@/components/GlobalSpaceListing.vue"
import DocCommonTreeView from "../../components/DocCommonTreeView.vue";
import ModalSaveTagPopup from "./Modal/ModalSaveTagPopup.vue";
import SignInAgain from "../../components/Common/Modal/SignInAgain.vue";
export default {
    components: {
        SignInAgain,
        LeftMenu,
        RightContent,
        Listing,
        ManageFolder,
        ModalAddGroup,
        docShare,
        ModalAddTag,
        ModalMoveFolderFiles,
        GlobalListing,
        Ownertree,
        DocCommonTreeView,
        ModalSaveTagPopup
       
    },
    data() {
        return {
            showSignInAgain:false,
            isLoading: false,
            loggeduserid: null,
            companyId: null,
            SharedUserList:[],
            folderarray: [],
            FindalFolderArray: [],
            FilesListing:[],
            FilesListingData: [],
            folderTreeList: [],
            sharedFolder: [],
            SharedFolderParent: [],
            SharedWith: [],
            folderId: null,
            showmodal: false,
            selectedTags:'',
            showmodalTag: false,
            ShowModalAddGroup: false,
            ShowGruopListing: false,
            folderSummary: [],
            parentname: [],
            folderDetails: [],
            folderName: null,
            chkAddEditFolder: null,
            pageNo: 1,
            pageSize: 10,
            TotalPages: 0,
            totalRecords: 0,
            parentId: null,
            sharemodal: false,
            showmovefolderpopup: false,
            moveFolderObj: [],
            folderFileId: "",
            manageFolderPopupLabel: "",
            docCode: 0,
            fileName: null,
            fileId: null,
            sharedparentfolder: [],
            sharedChildFolder: [],
            sharedFilesListingData: [],
            isShowSharedListing: false,
            isShowMySpaceListing: true,
            folderPermission: "",
            recentFolderList: [],
            pinnedFolderList: [],
            RecentFolderArray: [],
            pinnedFolderArray: [],
            organizationSpace: [],
            mySpaceOrOrganization: null,
            commonParentName: "My Space",
            isShowGlobalSpace: false,
            breadcrumbForManagePopup: "",
            refCode: 'MySpace',
            showmodalmovepopup: false,
            checkActionType: '',
            showUploadDiv: false,
            generateJSONData: [],
            sourceIds: '',
            IsDocCode: '',
            moveObj: [],
            saveTagPopupShow: false,
            yourobj:[],
            routeClass:'My Space',
            isDivActiveFromTagListing:false,
            isDivActive:false,
            storePageNo:null,
            Name:'',
            listingView:'ListView',
            str:'',
            addClsLeftMenu:false,
            additionalStorage:"",
            additionalStorageFolderId:'',
            additionalOrganizationSpace:[],
            treeOpenCode:'',
            AdditionalStorageData:[],
            AdditionalFolderIdExist:"",
            AdditionalStorageDataForBreadCrumb:[],
            checkMoveTypeAdditionalOrDefault:'Default',
            AdditionalFolderArray:[],
            CheckMultiselectMove:false,
            isShowNetworkSharedDrive:false,
            fileUrl:'',
            userEmail:'',
            password:'',
            networkBreadcrumb:"",
            LeftComponentRefresh:0,
            ListingComponentRefresh:0,
            RefreshAdditionalLeftMenu:0
        }
    },
    created: function () {
        //debugger
        var vm = this;
        vm.GetConfigValue();
        const queryString = window.location.search;
        this.pageSize=this.GetUserInfo.PageSize;
        const urlParams = new URLSearchParams(queryString);
        const commonparentname = urlParams.get('ParentName')
        const folderid = urlParams.get('FolderId')
        const refcode=urlParams.get('RefCode');
        const addclass=urlParams.get('AddClass');
        vm.folderId = vm.$route.params.FolderId==undefined?folderid:vm.$route.params.FolderId;
        vm.loggeduserid = vm.GetUserInfo.ID;
         vm.routeClass=vm.$route.params.AddClass==undefined?addclass:vm.$route.params.AddClass;
         if(window.location.search.split("=")[2]==undefined){
            vm.commonParentName = vm.$route.params.ParentName==undefined?"My Space":vm.$route.params.ParentName;
         }
         else{
            vm.commonParentName = vm.$route.params.ParentName==undefined?commonparentname.replace("+"," "):vm.$route.params.ParentName;
         }
        if(refcode==null){
            vm.refCode=vm.$route.params.RefCode==undefined?"MySpace":vm.$route.params.RefCode;
            if(vm.$route.params.RefCode=="AdditionalStorage"){
                vm.refCode='Organization';
                vm.additionalStorage=vm.$route.params.AdditionalStorageId;
            }
        }
        else{
            if(refcode!="AdditionalStorage")
            {
                vm.refCode=vm.$route.params.RefCode==undefined?refcode:vm.$route.params.RefCode;
            }
            else{
                vm.refCode=vm.commonParentName=="My Space"?"MySpace":vm.commonParentName;
                vm.additionalStorage=vm.$route.query.AdditionalStorageId;
            }
            
        }
        if( vm.refCode=="Shared"){
            vm.StorageDocumentListing(vm.folderId);
        }
            console.log("refcode",vm.refcode)
        
        vm.companyId = vm.GetUserInfo.CompanyId;
        vm.organizationSpace=[];
        vm.additionalOrganizationSpace=[];
        vm.GetFullTree();
        vm.StorageDocumentListing(vm.folderId);
        vm.GetSharedFolder();
        vm.GetAdditionalStorage();
    },
    mounted: function () {
        var vm=this;
        $("#FolderFullTree").treeview();
        $("body").on("click", "#FolderFullTree .folderlink", function () {
            $("#FolderFullTree .folderlink").removeClass("selectedfolder");
            $(this).addClass("selectedfolder");
        });
        $("#FolderFullTree3").treeview();
        $("body").on("click", "#FolderFullTree3 .folderlink", function () {
            $("#FolderFullTree3 .folderlink").removeClass("selectedfolder");
            $(this).addClass("selectedfolder");
        });
        if(vm.$route.query.AdditionalStorage!="" && vm.$route.query.AdditionalStorage!=undefined){
            vm.additionalStorageFolderId=vm.$route.query.AdditionalStorage;
        }
        
    },
    handleArray(items) {
        this.networkSharedData=items
        this.networksharedmodal=true;
    },
    updated: function () {
       // debugger
        var vm=this;
        vm.HighlightSelectedFolder();
        vm.BindActionButtonEvent();
        if(vm.additionalStorage!=null && vm.mySpaceOrOrganization==1 && (vm.additionalStorageFolderId==null || vm.additionalStorageFolderId=="")){
            vm.GetAdditionalOrganizationSpaceId();
        }
    },
    methods: {
        // Files and Folder Listing 
        StorageDocumentListing(folderiddata, Parentid, actionVal, name, searchcondition, sortBy, sortExp, listingCode, sharedPermission,pageno,clikType,addFolderId,driveId) {
            debugger
            var vm = this;
            const queryString = window.location.search;
            //vm.ListingComponentRefresh+=1;
            const urlParams = new URLSearchParams(queryString);
            vm.routeClass=null;
            if(addFolderId!=null){
                vm.additionalStorageFolderId=addFolderId;
            }
            else{
                vm.additionalStorageFolderId="";
                if((vm.$route.query.AdditionalStorageId==null || vm.$route.query.AdditionalStorageId==undefined || vm.$route.query.AdditionalStorageId=="") && vm.additionalStorage==null && vm.additionalStorage==undefined && vm.additionalStorage==""){
                    vm.additionalStorage="";
                }
            }
            vm.isLoading = true;
            if (name != undefined) {
                vm.commonParentName = name;
            }
            if (listingCode != undefined) {
                vm.refCode = listingCode;
            }
            if (vm.commonParentName=="My Space" || listingCode == "MySpace" || name=="My Space" || listingCode == "Recent" || listingCode == "Pinned") {
                vm.isShowGlobalSpace = false;
                if(vm.additionalStorage=='' || vm.additionalStorage==null || driveId!=null){
                    vm.additionalStorage=driveId
                }
                listingCode=listingCode=='Recent'?'Recently Added':listingCode;
                listingCode=listingCode=='Pinned'?'Pinned Folder':listingCode;
                vm.commonParentName=listingCode=='MySpace' || listingCode==null?'My Space':listingCode;
                vm.isShowMySpaceListing = true;
                vm.isShowSharedListing = false;
                vm.isShowNetworkSharedDrive=false;
                vm.mySpaceOrOrganization = "";
                vm.routeClass='a'+folderiddata;
                vm.treeOpenCode=listingCode;
            }
            if (listingCode == "AdditionalStorage" || listingCode == "Organization" || vm.commonParentName=="Organization Space" || vm.commonParentName=="Organization" || name == "Organization Space" || actionVal == 1) {
                vm.isShowGlobalSpace = true;
                if(vm.additionalStorage=='' || vm.additionalStorage==null || driveId!=null){
                    vm.additionalStorage=driveId
                }
                vm.routeClass='a'+folderiddata;
                vm.additionalStorageFolderId=name=="AdditionalStorage" || vm.additionalStorageFolderId!="" || vm.additionalStorageFolderId!=null?vm.additionalStorageFolderId:null;
                vm.isShowMySpaceListing = false;
                vm.isShowSharedListing = false;
                vm.isShowNetworkSharedDrive=false;
                vm.mySpaceOrOrganization = 1;
                vm.showUploadDiv = false;
                 vm.routeClass='a'+folderiddata;
                 vm.treeOpenCode=listingCode;
            }
            if (listingCode == "Shared" || name == "Shared" || vm.commonParentName=="Shared Folders" ) {
                vm.isShowSharedListing = true;
                vm.isShowMySpaceListing = false;
                vm.isShowGlobalSpace = false;
                vm.refCode="Shared";
                vm.isShowNetworkSharedDrive=false;
                vm.FilesListingData=[];
                vm.showUploadDiv = false;
                 vm.routeClass='a'+folderiddata;
            }
            if (listingCode == "Recent" || listingCode == "Pinned") {
                vm.showUploadDiv = false;
            }
            if (listingCode == "MySpace") {
                vm.showUploadDiv = true;
            }
            if ((folderiddata!=0 || folderiddata=="")  && vm.commonParentName!=""){
                this.listingView='ListView'
            }
            vm.folderPermission = sharedPermission==undefined?vm.folderPermission:sharedPermission;
            vm.totalRecords = 0;
            vm.folderId = folderiddata;
            if(clikType!='Tree' && vm.additionalStorage==null){
                 vm.GetFullTree();
                 vm.addClsLeftMenu=true;
            }
            vm.parentId = Parentid;
            if (folderiddata == undefined || folderiddata == '' ||  folderiddata == '0') {
                folderiddata = 0;
                vm.addClsLeftMenu=false;
                vm.pageNo=pageno==undefined || pageno==""?vm.pageNo:pageno;
                vm.storePageNo=pageno==undefined?vm.pageNo:pageno;
            }
            else if(urlParams.get('FolderId')==vm.folderId ){
                vm.pageNo=pageno==undefined || pageno==""?vm.pageNo:pageno;
            }
            else{
                vm.pageNo=1;
            }
            var params = `folderId=${folderiddata}&pageNo=${vm.pageNo}&pageSize=${vm.pageSize}&searchFilter=${searchcondition}&sortBy=${sortBy}&sortExp=${sortExp}&refCode=${vm.refCode}&additionalStorage=${vm.additionalStorage==undefined?"":vm.additionalStorage}`;
            if (searchcondition == undefined) {
                params = `folderId=${folderiddata}&pageNo=${vm.pageNo}&pageSize=${vm.pageSize}&searchFilter=&sortBy=${sortBy}&sortExp=${sortExp}&refCode=${vm.refCode}&additionalStorage=${vm.additionalStorage==undefined?"":vm.additionalStorage}`;
            }
            DataService.GetFolderList(params).then((response) => {
                vm.isLoading = false;
                if(response.data.FolderData!=undefined){
                    vm.FilesListingData = response.data.FolderData;
                    if (vm.FilesListingData.length > 0) {
                        vm.totalRecords = vm.FilesListingData[0].totalRecords;
                    }   
                    else{
                        vm.FilesListingData=[];
                    }
                
                    if(vm.refCode=='Shared'){
                        vm.FilesListingData.forEach(function (item, index){
                            vm.folderPermission= vm.FilesListingData[index].PERMISSION;
                        });
                    }
                    vm.TotalPages = Math.ceil(vm.totalRecords / this.pageSize);
                    vm.BreadCrumb(vm.commonParentName=="MySpace"?"My Space":vm.commonParentName, folderiddata,Parentid);
                }else{
                    vm.FilesListingData=[];
                }
              $('.chkItems:checkbox:checked,#chkAll_0').prop("checked", false).removeAttr('checked');
              $('.chkItems:checkbox:checked').prop("checked", false).removeAttr('checked');
                this.$refs.listing.ShowUpload(true);
                if(vm.additionalStorage!=undefined){
                    vm.GetAdditionalStorage();
                }
                setTimeout(function () {
                    vm.ResponsiveDataTable('tblFileList')
                }, 500); 
                setTimeout(function () { vm.CheckBoxBootstrap() }, 100);
            })

        },
        //Folder Listing with sub folder 
        GetFullTree() {
            var vm = this;
            vm.FindalFolderArray=[]
            vm.additionalOrganizationSpace=[];
            DataService.FolderFullTreeView().then((response) => {
                
                console.log("Response Result:-",response.data.folderTreeList)
                response.data.folderTreeList.forEach((value, index) => {
                    if (value.OWNER_USER_ID == vm.loggeduserid && value.IsGlobal == 0 && value.additional_storage_id==null) {
                        var CheckIfExist = vm.FindalFolderArray.filter(function (el) {
                            return el.FOLDER_ID == value.FOLDER_ID;
                        });

                        if (CheckIfExist.length == 0) {
                            if (value.FOLDER_PARENT_ID == null && value.additional_storage_id==null) {
                                let folderId = value.FOLDER_ID
                                let rslt = vm.getChildFolder(folderId, value, response.data.folderTreeList)
                                
                                console.log("response folderTreeList:-",response.data.folderTreeList)
                                vm.FindalFolderArray.push(rslt)
                            }
                        }
                    }
                });
                console.log("vm.FindalFolderArray",vm.FindalFolderArray)
                vm.folderTreeList = response.data.folderTreeList;
                vm.sharedFolder = response.data.sharedTreeList;
                vm.GetSharedFolder();
                vm.GetRecentlyAddPinnedFolder();
                vm.organizationSpace=[];
                vm.GetOrganizationSpace();
            });
        },
        HighlightSelectedFolder:function(){
            var vm=this;
            if(vm.commonParentName=="MySpace" || vm.commonParentName=="My Space"){
                var element = document.getElementById("MySpace");
                var Additionalelement = document.getElementById("AdditionalMySpace");
                if(vm.folderId!=null && vm.folderId!=0 && vm.folderId!=undefined){
                    element.classList.remove("selectedfolder");
                    Additionalelement.classList.remove("selectedfolder");
                }else{
                    if(vm.additionalStorage!=null){
                        Additionalelement.classList.add("selectedfolder");
                        element.classList.remove("selectedfolder");
                    }
                    else{
                        Additionalelement.classList.remove("selectedfolder");
                        element.classList.add("selectedfolder");
                    }
                }
            }
            $("#FolderFullTree3").treeview();
            $("body").on("click", "#FolderFullTree3 .folderlink", function () {
                $("#FolderFullTree3 .folderlink").removeClass("selectedfolder");
                $("#AdditionalMySpace").removeClass("selectedfolder");
                $("#MySpace").removeClass("selectedfolder");
                $(this).addClass("selectedfolder");
            });
        },
        GetSharedFolder: function () {
            var vm = this;
            DataService.GetSharedFolderTree().then((response) => {

                vm.sharedparentfolder = response.data.SharedFolderData;
                 vm.str="";
                vm.sharedparentfolder.forEach((value, index) => {
                    if (value.SHARED_USER_ID == vm.loggeduserid && value.additional_storage_id==null) {
                        var CheckIfExist = vm.sharedChildFolder.filter(function (el) {
                            return el.FOLDER_ID == value.FOLDER_ID;
                        });


                        if (CheckIfExist.length == 0) {
                            if (value.FOLDER_PARENT_ID == null) {
                                let folderId = value.FOLDER_ID
                                vm.str+=folderId + ',';
                                let rslt = vm.getsharedChildFolder(folderId, value, vm.folderTreeList);
                                vm.sharedChildFolder.push(rslt)
                            }
                            else{
                                let folderId = value.FOLDER_ID
                                if((vm.str.includes(folderId))==false){
                                    let rslt = vm.getsharedChildFolder(folderId, value, vm.folderTreeList);
                                    vm.sharedChildFolder.push(rslt)
                                }  
                            }
                        }
                    }

                });

            });
        },
        getsharedChildFolder: function (folderId, currentItem, data) {
            
            let ths = this;
            let retrunArray = currentItem
            var childArray = data.filter(function (el) {
                return el.FOLDER_PARENT_ID == folderId;
            });
            let finalChildArray = [];
            childArray.forEach((value, index) => {
                let ChildfolderId = value.FOLDER_ID
                ths.str+=ChildfolderId +',';
                var CheckIfExist1 = finalChildArray.filter(function (el) {
                    return el.FOLDER_ID == value.FOLDER_PARENT_ID;
                });
                if (CheckIfExist1.length == 0) {
                    var CheckIfExist = data.filter(function (el) {

                        return el.FOLDER_PARENT_ID == ChildfolderId;


                    });
                    if (CheckIfExist != null && CheckIfExist.length > 0) {
                        let rslt = ths.getsharedChildFolder(ChildfolderId, value, data);
                        finalChildArray.push(rslt);
                    } else {
                        finalChildArray.push(value);
                    }
                }
            });
            retrunArray.chidFolder = finalChildArray;
            return retrunArray
        },
        MarkAsFavourite: function (jsonResult) {
            var vm = this;
            vm.isLoading = true;
            vm.yourobj=[];
            let obj = {}
            vm.MarkAsFavoriteWithButton = true;
            var val = "";
            // var data = { jsonResult};  

          
            var CheckIfExist = jsonResult.filter(function (el) {
                return el.pinId == 0;
            });
            if (CheckIfExist.length > 0) {
                CheckIfExist.forEach((item, index) => {
                    let obj = {
                        Id: item.Id,
                        ModuleName: 'DocStorage',
                        ActionType: 'Pin'
                    }
                    vm.yourobj.push(obj)
                });
            }


            let pinunpinObj = JSON.stringify(vm.yourobj);
